public class PowerOfThree {
    public static boolean isPowerOfThree(int n) {
        // Check for edge cases
        if (n < 1 || n % 3 != 0) {
            return false;
        }

        // Loop through all powers of 3 until we reach or exceed n
        while (true) {
            int powerOfThree = n / 3;
            if (powerOfThree * 3 == n) {
                return true;
            } else if (powerOfThree * 3 > n) {
                break;
            }
        }

        return false;
    }

    public static void main(String[] args) {
        System.out.println(isPowerOfThree(27)); // true
        System.out.println(isPowerOfThree(0)); // false
        System.out.println(isPowerOfThree(-1)); // false
        System.out.println(isPowerOfThree(8)); // true
    }
}
```

